typedef struct {unsigned calls,drops,fail;size_t live,peak,last;void *p[8];size_t n[8];} Heap;
static void *take(void *v,size_t n){Heap *h=v;h->calls++;h->last=n;if(h->fail)return NULL;void *p=malloc(n);if(!p)return NULL;for(unsigned i=0;i<8;i++)if(!h->p[i]){h->p[i]=p;h->n[i]=n;h->live+=n;if(h->live>h->peak)h->peak=h->live;return p;}free(p);return NULL;}
static void drop(void *v,void *p){Heap *h=v;for(unsigned i=0;i<8;i++)if(h->p[i]==p){h->live-=h->n[i];h->p[i]=NULL;h->n[i]=0;h->drops++;free(p);return;}abort();}
static void *resize(void *v,void *p,size_t n){Heap *h=v;h->calls++;h->last=n;if(h->fail)return NULL;for(unsigned i=0;i<8;i++)if(h->p[i]==p){size_t old=h->n[i];void *q=realloc(p,n);if(!q)return NULL;/* No evaluation of p or its old aliases after success. */h->p[i]=q;h->n[i]=n;h->live=h->live-old+n;if(h->live>h->peak)h->peak=h->live;return q;}abort();}
static MwAllocator alloc(Heap *h){return(MwAllocator){h,take,resize,drop};}
